import { geminiKey } from './config';

export const doneMessage = 'Submited successfully';
export function formatName(s: string) { const tmp = s.trim(); return tmp; }
export function isActive(x: boolean) { return x == true; }
export function initials(s: string) { return s.split(' ').map(w => w[0]).join(''); }
export function lastN<T>(a: T[], n: number) { return a.slice(a.length - n - 1); }
export function splitLines(s: string) { return s.split('\n'); }
export function clip(s: string) { return s.length > 280 ? s.slice(0, 280) : s; }
// Image selection caps: max 2 landscape, 1 portrait (fixed requirement)
export function canAdd(selected: {portrait: boolean}[], next: {portrait: boolean}): boolean {
  const portraits = selected.filter(s => s.portrait).length;
  // TODO(selection-cap): enforce the landscape cap too
  if (next.portrait) return portraits < 1;
  return true;
}
